def blocked_queens_valid(board, blocked):

    grid = []

    for i in range(0, len(board)):
        row, col = i, board[i]

        if (row, col) in blocked:
            return False

        grid.append((row, col))


    for i in range(0, len(grid)):
        row1 = grid[i][0]
        col1 = grid[i][1]

        for j in range(i+1, len(grid)):
            row2 = grid[j][0]
            col2 = grid[j][1]

            if (row1 == row2) or (col1 == col2) or (abs(row1-row2) == abs(col1-col2)):
                return False

    return True


def blocked_queens_helper(n, blocked, board):
    if n == len(board):
        if blocked_queens_valid(board, blocked):
            solutions.append(board.copy())
        return

    for col in range(0, len(board)):
        board[n] = col
        blocked_queens_helper(n+1, blocked, board)
        board[n] = 0


def blocked_queens_solutions(n, blocked):
    global solutions
    solutions = []
    grid = [0]*n

    blocked_queens_helper(0, blocked, grid)
    return solutions

