import random


class CrossOutPuzzle(object):

    def __init__(self, board):
        self.board = board

    def get_board(self):
        return self.board

    def perform_move(self, row, col):
        for col1 in range(0, len(self.board[0])):
            self.board[row][col1] = not self.board[row][col1]

        for row1 in range(0, len(self.board)):
            if row1 != row:
                self.board[row1][col] = not self.board[row1][col]

    def scramble(self):
        import random
        for row in range(0, len(self.board)):
            for col in range(0, len(self.board[0])):
                if random.random() < 0.5:
                    self.perform_move(row, col)

    def is_solved(self):
        return not any([True in row for row in self.board])

    def copy(self):
        return CrossOutPuzzle([row.copy() for row in self.board])

    def successors(self):
        for row in range(0, len(self.board)):
            for col in range(0, len(self.board[0])):
                new_board_copy = self.copy()
                new_board_copy.perform_move(row, col)
                yield ((row, col), new_board_copy)

    def find_solution(self):
        from collections import deque
        queue = deque()

        visited_set = set()

        queue.append((self.copy(), []))

        while queue:
            entry, moves = queue.popleft()
            entry_tuple = tuple(tuple(row) for row in entry.get_board())

            if entry_tuple in visited_set:
                continue

            visited_set.add(entry_tuple)

            if entry.is_solved():
                return moves

            for move, mod_board in entry.successors():
                queue.append((mod_board, moves + [move]))

def create_cross_puzzle(rows, cols):
    return CrossOutPuzzle([[False]*cols for _ in range(rows)])

